import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, it } from "node:test";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("../../", import.meta.url));

/**
 * The README's proof images are generated by `pnpm capture` and `pnpm og`.
 * These tests cannot tell whether a screenshot is out of date — that needs a
 * human eye — but they do catch the failures that actually happen: an image
 * deleted, emptied, truncated, or regenerated at the wrong size.
 */
const EXPECTED_PNG_SIZE: Record<string, { width: number; height: number }> = {
  "docs/landing.png": { width: 2880, height: 1800 },
  "docs/dashboard.png": { width: 2880, height: 1800 },
  "docs/dashboard-dark.png": { width: 2880, height: 1800 },
  "docs/keys.png": { width: 2880, height: 1800 },
  "docs/dashboard-mobile.png": { width: 780, height: 1688 },
  "apps/web/public/og.png": { width: 1200, height: 630 },
};

const EXPECTED_GIF_SIZE = { width: 960, height: 618 };

function readmeImageReferences(): string[] {
  const readme = readFileSync(join(ROOT, "README.md"), "utf8");
  const found = new Set<string>();

  for (const match of readme.matchAll(/!\[[^\]]*\]\(([^)]+\.(?:png|gif))\)/g)) {
    if (match[1]) found.add(match[1]);
  }
  for (const match of readme.matchAll(/src="([^"]+\.(?:png|gif))"/g)) {
    if (match[1]) found.add(match[1]);
  }

  return [...found];
}

function pngSize(buffer: Buffer): { width: number; height: number } {
  assert.equal(buffer.subarray(1, 4).toString("ascii"), "PNG", "not a PNG");

  return {
    width: buffer.readUInt32BE(16),
    height: buffer.readUInt32BE(20),
  };
}

describe("README proof images", () => {
  const references = readmeImageReferences();

  it("references enough images to be proof rather than decoration", () => {
    assert.ok(references.length >= 4, `only ${references.length} images referenced`);
  });

  for (const reference of references) {
    it(`${reference} exists and is not empty`, () => {
      const path = join(ROOT, reference);
      assert.ok(existsSync(path), `${reference} is referenced but missing`);

      const buffer = readFileSync(path);
      assert.ok(buffer.byteLength > 10_000, `${reference} is only ${buffer.byteLength} bytes`);
    });
  }

  for (const [reference, expected] of Object.entries(EXPECTED_PNG_SIZE)) {
    it(`${reference} is ${expected.width}x${expected.height}`, () => {
      const buffer = readFileSync(join(ROOT, reference));
      const actual = pngSize(buffer);

      assert.equal(actual.width, expected.width, "width changed");
      assert.equal(actual.height, expected.height, "height changed");
    });
  }
});

describe("demo GIF", () => {
  const buffer = readFileSync(join(ROOT, "docs/demo.gif"));

  it("is a GIF", () => {
    assert.match(buffer.subarray(0, 6).toString("ascii"), /^GIF8[79]a$/);
  });

  it("loops, so it animates in the README", () => {
    assert.ok(buffer.includes(Buffer.from("NETSCAPE2.0")), "missing the loop extension");
  });

  it(`is ${EXPECTED_GIF_SIZE.width}x${EXPECTED_GIF_SIZE.height}`, () => {
    assert.equal(buffer.readUInt16LE(6), EXPECTED_GIF_SIZE.width);
    assert.equal(buffer.readUInt16LE(8), EXPECTED_GIF_SIZE.height);
  });

  it("stays small enough to load in a README", () => {
    assert.ok(buffer.byteLength < 2_000_000, `GIF is ${(buffer.byteLength / 1e6).toFixed(1)} MB`);
  });
});
